import { Component } from '@angular/core';

@Component({
  selector: 'app-project-card',
  template: `
    <div class="card">
      <h2>{{ title }}</h2>
      <p>Status: {{ isActive ? 'ONLINE' : 'OFFLINE' }}</p>
      <button (click)="toggleStatus()">Toggle</button>
    </div>
  `,
  styles: [`
    .card { border: 1px solid cyan; padding: 20px; }
  `]
})
export class ProjectCardComponent {
  title = 'Project Atlas';
  isActive = true;
  toggleStatus() { this.isActive = !this.isActive; }
}

@NgModule({
  declarations: [AppComponent, ProjectCardComponent],
  imports: [BrowserModule, ReactiveFormsModule, RouterModule],
  providers: [ProjectService, AuthGuard],
  bootstrap: [AppComponent]
})
export class AppModule {}

// Service injection in component
@Component({ selector: 'app-projects', template: '...' })
export class ProjectsComponent {
  constructor(private projectService: ProjectService) {}

  ngOnInit() {
    this.projects = this.projectService.getAll();
  }
}

const routes: Routes = [
  { path: '', component: HomeComponent },
  { path: 'dashboard', component: DashboardComponent,
    canActivate: [AuthGuard] },
  // Lazy loading
  { path: 'projects',
    loadChildren: () => import('./projects/projects.module')
      .then(m => m.ProjectsModule) },
  { path: '**', redirectTo: '' }
];

@Injectable({ providedIn: 'root' })
export class ProjectService {
  private apiUrl = '/api/projects';

  constructor(private http: HttpClient) {}

  getProjects(): Observable<Project[]> {
    return this.http.get<Project[]>(this.apiUrl)
      .pipe(
        retry(3),
        catchError(err => {
          console.error('Request failed', err);
          return throwError(() => err);
        })
      );
  }
}

import { FormGroup, FormControl, Validators } from '@angular/forms';

export class ProjectFormComponent {
  projectForm = new FormGroup({
    userName: new FormControl('', [
      Validators.required,
      Validators.minLength(3)
    ]),
    destination: new FormControl('', Validators.required),
    access: new FormControl('alpha')
  });

  onSubmit() {
    if (this.projectForm.valid) {
      console.log(this.projectForm.value);
    }
  }
}

import { BehaviorSubject, interval } from 'rxjs';
import { map, filter, debounceTime } from 'rxjs/operators';

// Search input stream with debounce
this.searchControl.valueChanges.pipe(
  debounceTime(300),
  filter(query => query.length >= 2),
  switchMap(query => this.projectService.search(query))
).subscribe(results => this.displayResults(results));

// State management with BehaviorSubject
const usageLevel$ = new BehaviorSubject<number>(100);
usageLevel$.next(85); // Update value
usageLevel$.subscribe(val => console.log('Usage:', val));

import { signal, computed, effect } from '@angular/core';

export class UsageComponent {
  usage = signal(0);
  usageRate = computed(() => this.usage() * 2.5);

  constructor() {
    effect(() => {
      console.log(`Usage: ${this.usage()}, Rate: ${this.usageRate()}`);
      if (this.usage() > 90) {
        console.warn('USAGE LIMIT REACHED!');
      }
    });
  }

  increase() {
    this.usage.update(val => Math.min(100, val + 10));
  }
}
